import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: true,
    environment: "node",
    include: ["tests/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      // server.ts is the process entrypoint (starts Fastify, binds ports);
      // it is exercised by running the app, not by unit tests.
      // src/generated/prisma is Prisma-generated client code (not hand-written,
      // regenerated by `prisma generate`); it has no behavior of ours to unit test.
      // runnerTypes.ts contains only `interface`/`type` declarations with zero
      // executable statements, so v8 reports it as 0% covered no matter what —
      // there is nothing a test could execute.
      exclude: ["src/server.ts", "src/generated/prisma/**", "src/runtime/runnerTypes.ts"],
      reporter: ["text", "json-summary", "html"],
      reportsDirectory: "coverage",
    },
  },
});
